{"task_id": "T35", "code": "def solve(grid):
    """Count islands in a possibly ragged binary grid.
    An island is a group of adjacent cells with value 1, connected orthogonally.
    """
    if not grid:
        return 0
    visited = set()
    n = len(grid)
    def neighbors(i, j):
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        visited.add((i, j))
        while stack:
            x, y = stack.pop()
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    visited.add((nx, ny))
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count
"}

