def solve(a, x):
    """Return the leftmost index at which ``x`` can be inserted into the sorted list ``a``.
    Implements binary search in O(log n) time and works for empty lists.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def solve(n):
    """Return number of prime numbers strictly less than n."""
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    max_p = int(math.isqrt(limit))
    for p in range(2, max_p + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
    return sum(sieve)

