def solve(line):
    """Parse a CSV line into fields.
    Supports quoted fields with double quotes. Inside quotes, two consecutive double quotes represent a literal quote.
    Empty line returns [''].
    """
    if line == "":
        return [""]
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            buf = []
            while i < n:
                ch = line[i]
                if ch == '"':
                    # Escaped quote?
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    else:
                        i += 1  # consume closing quote
                        break
                else:
                    buf.append(ch)
                    i += 1
            fields.append(''.join(buf))
            # Skip following comma if present
            if i < n and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    # Trailing comma indicates an extra empty field
    if line and line[-1] == ',':
        fields.append('')
    return fields

