    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i<0 or i>=rows or j<0 or j>=cols:
                continue
            if visited[i][j] or grid[i][j]==0:
                continue
            visited[i][j]=True
            stack.extend([(i-1,j),(i+1,j),(i-1,j-1),(i-1,j+1),(i+1,j-1),(i+0,j-1),(i+0,j+1)])
    count=0
    for i in range(rows):
        for j in range(cols):
