def solve(n):
    """Count the number of prime numbers strictly less than n using the Sieve of Eratosthenes."""
    if n <= 2:
        return 0
    limit = n - 1
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = [False] * ((limit - start) // step + 1)
    return sum(sieve)

